import{_ as d,C as p,o as s,c as l,j as e,a as t,b as c,w as n,E as i,a6 as r,a5 as u}from"./chunks/framework.BEZBAInb.js";const x=JSON.parse('{"title":"普通对话","description":"","frontmatter":{"title":"普通对话","order":3},"headers":[],"relativePath":"zh/latest/tutorial/script/conversation.md","filePath":"zh/latest/tutorial/script/conversation.md","lastUpdated":1788455378000}'),h={name:"zh/latest/tutorial/script/conversation.md"};function q(m,a,_,b,g,k){const o=p("Mermaid");return s(),l("div",null,[a[1]||(a[1]=e("h1",{id:"普通对话",tabindex:"-1"},[t("普通对话 "),e("a",{class:"header-anchor",href:"#普通对话","aria-label":'Permalink to "普通对话"'},"​")],-1)),a[2]||(a[2]=e("h2",{id:"功能描述",tabindex:"-1"},[t("功能描述 "),e("a",{class:"header-anchor",href:"#功能描述","aria-label":'Permalink to "功能描述"'},"​")],-1)),(s(),c(r,null,{default:n(()=>[i(o,{id:"mermaid-6",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%E5%AF%B9%E8%AF%9D%E6%A1%86%5D%20--%3E%20B%5B%E8%A7%92%E8%89%B2%E5%A7%93%E5%90%8D%5D%0A%20%20%20%20A%20--%3E%20D%5B%E5%AF%B9%E8%AF%9D%E6%96%87%E6%9C%AC%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=u(`<p>普通对话是游戏中常见的交互方式，用于角色与玩家之间的交流，通过角色名称、对话文本来呈现对话内容。</p><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[演员标识符、变量或署名文本] &quot;对话文本&quot; [配音标签] [参数=值 ...]</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>说话者</td><td>是</td><td><code>alice</code>、<code>$speaker</code> 或 <code>&quot;旁白&quot;</code></td><td>静态演员、保存演员 ID 的变量，或纯文本署名</td></tr><tr><td>对话文本</td><td>是</td><td><code>你好，我叫爱丽丝！</code></td><td>角色要说的话</td></tr><tr><td>配音标签</td><td>否</td><td><code>alice_intro_01</code></td><td>可选的标签，用于标识配音文件</td></tr><tr><td><code>speed</code></td><td>否</td><td><code>[speed=1.5]</code></td><td>本句打字速度倍率，必须大于 <code>0</code></td></tr><tr><td><code>interval</code></td><td>否</td><td><code>[interval=0.03]</code></td><td>本句每个字符的打字间隔（秒），不能与 <code>speed</code> 同时使用</td></tr></tbody></table><p>设置了配音标签并成功播放语音时，对话框默认会显示音频进度；没有配音标签或语音播放结束后不会显示进度。如需关闭该功能，可以在对话框节点 <code>KonadoDialogueBox</code> 上关闭 <code>show_voice_progress</code>。进度显示样式可以在 <code>res://addons/konado/templates/default/voice_progress_display.tscn</code> 中自定义。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 普通对话</span></span>
<span class="line"><span>alice &quot;你好，我叫爱丽丝！&quot; alice_intro_01</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 单独调整本句的打字速度</span></span>
<span class="line"><span>alice &quot;这一句会显示得更快。&quot; [speed=1.5]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 纯文本署名，不要求存在对应演员</span></span>
<span class="line"><span>&quot;narrator&quot; &quot;暴风雨越来越猛烈了...&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 使用临时变量或持久变量动态选择演员</span></span>
<span class="line"><span>set $speaker &quot;alice&quot;</span></span>
<span class="line"><span>set %current_speaker &quot;alice&quot;</span></span>
<span class="line"><span>$speaker &quot;今天由变量决定谁在说话。&quot;</span></span>
<span class="line"><span>%current_speaker &quot;持久变量同样可以作为说话者。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 带插值的署名文本</span></span>
<span class="line"><span>set $guest_index 2</span></span>
<span class="line"><span>&quot;访客 $guest_index&quot; &quot;很高兴见到你。&quot;</span></span></code></pre></div><p>裸名称始终表示演员标识符，编辑器可以对其补全、检查、跳转和重命名。<code>$name</code> 与 <code>%name</code> 始终表示临时变量和持久变量，变量值必须是非空的字符串演员 ID；变量不存在或类型错误时运行会失败，不会回退成同名字符串。带引号的署名始终是可本地化文本，并支持 <code>$name</code>、<code>%name</code> 插值；使用空字符串可隐藏署名，插值变量不存在时会保留原占位符并输出警告。旧版的 <code>&quot;alice&quot; &quot;...&quot;</code> 写法仍可使用；当署名与演员 ID 相同时，运行时仍可自动高亮该演员。</p>`,9))])}const f=d(h,[["render",q]]);export{x as __pageData,f as default};
